function Nav({group,badge,go,settingsActive}){
 const dot=n=>n>0&&<span className="min-w-[18px] rounded-full bg-[#efbd63] px-1 text-center text-[10px] font-medium leading-[18px] text-black">{n>99?'99+':n}</span>;
 return <>
  <aside className="hidden lg:flex lg:sticky lg:top-24 lg:self-start flex-col gap-1">
   <p className="px-3 pb-3 text-[10px] uppercase tracking-[.3em] text-[#8d713d]">Estate Tea</p>
   {GROUPS.map(g=>{const on=group?.id===g.id&&!settingsActive,I=g.icon;return <button key={g.id} onClick={()=>go(g.sections[0][0])} className={`group relative flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] tracking-wide transition-colors ${on?'text-[#f1cf8b]':'text-gray-500 hover:text-gray-200'}`}>
    <span className={`absolute left-0 top-1/2 h-5 w-[2px] -translate-y-1/2 rounded-full transition-all ${on?'bg-[#efbd63] opacity-100':'opacity-0'}`}/>
    <I className="h-[17px] w-[17px]" strokeWidth={1.6}/><span className="flex-1 text-left">{g.label}</span>{dot(badge(g))}</button>})}
  </aside>
  <nav aria-label="Sections" className="lg:hidden fixed inset-x-0 bottom-0 z-[60] border-t border-white/[.07] bg-[#0a0a0a]/90 backdrop-blur-xl pb-[env(safe-area-inset-bottom)]">
   <div className="mx-auto grid max-w-md grid-cols-5">
    {GROUPS.map(g=>{const on=group?.id===g.id&&!settingsActive,I=g.icon,n=badge(g);return <button key={g.id} onClick={()=>go(g.sections[0][0])} className={`relative flex flex-col items-center gap-1 py-2.5 text-[10px] tracking-wide transition-colors ${on?'text-[#efbd63]':'text-gray-500'}`}>
     <span className={`absolute top-0 h-[2px] w-8 rounded-full transition-opacity ${on?'bg-[#efbd63] opacity-100':'opacity-0'}`}/>
     <span className="relative"><I className="h-5 w-5" strokeWidth={1.6}/>{n>0&&<span className="absolute -right-2.5 -top-1.5 min-w-[16px] rounded-full bg-[#efbd63] px-1 text-center text-[9px] font-medium leading-4 text-black">{n>99?'99+':n}</span>}</span>{g.label}</button>})}
   </div>
  </nav>
 </>;
}
function SubTabs({sections,active,go,counts}){
 return <div className="-mt-2 flex gap-1 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden border-b border-white/[.06]">
  {sections.map(([id,label])=>{const on=id===active,n=counts[id];return <button key={id} onClick={()=>go(id)} className={`relative shrink-0 px-3 pb-3 pt-1 text-[13px] transition-colors ${on?'text-[#f1cf8b]':'text-gray-500 hover:text-gray-300'}`}>
   {label}{n>0&&<span className="ml-1.5 text-[11px] text-[#efbd63]">{n}</span>}
   <span className={`absolute inset-x-3 -bottom-px h-px transition-opacity ${on?'bg-[#efbd63] opacity-100':'opacity-0'}`}/></button>})}
 </div>;
}

